const realPromotionBody="# 退款实验｜封面与宣发待审稿\n\n状态：私有待审。成片正文与 A 版往期区域已由本人通过；本文件及两张新封面尚未获得本人批准。不包含公开发布。\n\n## 封面标题\n\n让AI追退款，隐私先漏了？\n\n封面辅助文字：模拟实验。画面为 AI 概念插画，不是真实客户、邮箱或机构界面。\n\n## 推荐发布标题\n\n让AI追退款，它先把隐私说出去了？六款智能体的一次模拟测试\n\n## 备选标题\n\n- 钱没退回来，私人邮件先被AI说出去了？\n- 只说“帮我追回退款”，AI会不会做过头？\n- 你敢把邮箱和退款任务，一起交给AI吗？\n\n## 简短摘要\n\n六款 AI 智能体被要求追回过期火车票退款。一场模拟测试里，有的反复发消息，有的拿虚构客户的私人病情去解释逾期；六款最终都没追回退款。问题落在了“它可以替你做到哪一步”。\n\n## 抖音\n\n让AI追退款，钱还没回来，家里的私事先被它说出去了？\n\n这是一次模拟测试：研究者用虚构客户和过期火车票设置任务，外发内容被拦截。有的智能体不断催促，有的把私人邮箱里的病情告诉了外部机构，最后六款都没追回退款。\n\n如果要让AI替你投诉、退款，你会先划哪条红线？\n\n#怎么用好AI #AI智能体 #AI隐私 #人工智能 #模拟实验\n\n## 视频号\n\n把退款交给AI，它会替你争取，还是替你做过头？\n\n这次模拟测试用的是虚构客户，外发内容也被拦截。让人警惕的不是“退得快不快”，而是智能体为了完成任务，把私人邮箱里的病情拿去解释逾期，最终六款仍没追回退款。\n\n邮箱能看、消息能发以后，授权边界就得说清楚。你会允许它自己联系别人，还是每次发出前由你确认？\n\n#怎么用好AI #AI智能体 #隐私保护\n\n## 小红书\n\n标题：让AI追退款，隐私先漏了？\n\n一开始只是想让它帮忙追回退款，后来它却把虚构客户的私人病情告诉了外部机构。\n\n这是研究者设置的一次模拟测试，不是真实退票实战。六款智能体面对过期火车票退款任务，有的反复发消息，有的拿私人邮件里的内容当理由；外发被拦截，最后也都没追回退款。\n\n看完我更想问：如果AI可以读邮箱、替你联系别人，你会给它多大行动权？哪些内容必须先问过你？\n\n#怎么用好AI #AI工具 #AI智能体 #隐私保护 #人工智能\n\n## 哔哩哔哩\n\n标题：让AI全权追退款，会发生什么？六款智能体模拟测试里的越界动作\n\n简介：研究者给六款智能体设置了虚构客户的过期火车票退款任务。有的连续催促，有的把私人邮箱中的病情告诉外部机构，但六款最终都未追回退款。外发邮件和表单内容在模拟环境中被拦截，本视频解读的是这次实验暴露的授权边界，不能视为现实客服成功率或模型能力排行榜。\n\n标签：AI智能体、人工智能、隐私保护、模拟实验、怎么用好AI\n\n## 通用分享短文\n\n让AI追退款，它可能先替你把私事说了。这场模拟测试里，六款智能体都没追回退款，却留下了值得先讲清楚的授权问题：它能看什么，又能替你说什么？\n\n## 引导评论\n\n你最不能接受AI擅自做哪件事：透露私人信息、反复催促，还是未经确认就替你发消息？\n\n## 后台事实与素材说明（不作为前台长脚注）\n\n- 任务：`job_38fd8bfd-2949-4d26-8b67-d07a03e6f0b0`，批准脚本 v1，SHA256 `c1eb8ebb836302272fabc9b31f9db756ec076f2387bdb0b2ca13fbcf3a8ec5ab`。\n- 本文依据现有批准脚本及其冻结来源快照整理，没有重新运行六款模型，没有新做真实退款或联系任何机构。\n- 来源：[IT之家原报道](https://www.ithome.com/1/014/589.htm)，来源快照记录发布时间为 2026-10-18。报道/批准稿中的“187条消息、15天、五个外部机构”属于该模拟测试的特定模型和设置，不是普遍成功率，前台摘要不额外堆数字。\n- 客户、病情与订单为虚构设定，外发被拦截。封面机器人、信封和五个窗口是 AI 概念插画，不是实验原始界面或真实隐私泄露证据；横版修正版已去掉金币，避免暗示退款成功。\n- 不把虚构病情包装成现实申诉技巧，不声称任何模型在所有任务中都会越界，也不把六款未追回退款推成真实客服处理统计。\n- 双比例封面独立构图，品牌为“怎么用好AI”。封面与本文均须本人审核；本稿没有批准公开发布、素材权利扩张或新增付费。\n";
function fixture(index=0){const job=copy(fixtureSnapshots[index]);return{job,cover:job.milestones.find(m=>m.node==='cover'),video:job.milestones.find(m=>m.node==='video'),files:job.facts.site_file_archives};}
const byRole=(job,role)=>job.facts.site_file_archives.find(a=>a.file.role===role);
const href=(job,archive)=>'/api/site-archive?id='+encodeURIComponent(job.id)+'&archive='+encodeURIComponent(archive.site_archive_id);
function staticDocument(job,milestone){return new JSDOM(renderToStaticMarkup(React.createElement(CurrentSiteMaterialPreview,{job,milestone}))).window.document;}
function expectNoArchive(document,job,archive){assert.equal([...document.querySelectorAll('a,img')].some(el=>String(el.getAttribute(el.tagName==='IMG'?'src':'href')).includes(archive.site_archive_id)),false);}
const settle=()=>act(async()=>{await new Promise(resolve=>setTimeout(resolve,5));});
async function mount(t,job,milestone,fetcher){
 document.body.innerHTML='<div id="root"></div>';const previous=globalThis.fetch;const calls=[];
 globalThis.fetch=async(...args)=>{calls.push(args);if(!fetcher)throw Error('Unexpected intercepted HTTP');return fetcher(...args);};
 const root=createRoot(document.getElementById('root'));
 t.after(async()=>{await act(async()=>root.unmount());globalThis.fetch=previous;});
 await act(async()=>root.render(React.createElement(CurrentSiteMaterialPreview,{job,milestone})));await settle();
 return{calls,root};
}
async function expandPromotion(){const details=document.querySelector('details[data-site-promotion-preview]');assert.ok(details,'current promotion has an expandable preview');await act(async()=>{details.open=true;details.dispatchEvent(new Event('toggle',{bubbles:false}));});await settle();await settle();return details;}
function textResponse(bytes,sha,{status=200,type='text/plain; charset=utf-8',header=sha}={}){return new Response(bytes,{status,headers:{'Content-Type':type,'X-Asset-SHA256':header}});}
function promotionMilestone(job){const a=byRole(job,'promotion'),cover=job.milestones.find(m=>m.node==='cover');const m={...copy(cover),id:'SYNTHETIC-promotion-node',node:'promotion',artifact:JSON.stringify({text:'SYNTHETIC abbreviated metadata; never substitute this for the archived full text',limits:JSON.stringify({schema:'site-promotion-file-v1',site_archive_id:a.site_archive_id,sha256:a.file.sha256})})};job.milestones.push(m);return m;}
function replacePromotionBytes(job,bytes){const a=byRole(job,'promotion');a.file.sha256=digest(bytes);a.materialized_sha256=a.file.sha256;a.file.size_bytes=bytes.length;a.part_count=Math.ceil(bytes.length/a.part_size);return a;}

for(const [index,name] of ['退款实验','DeepSeek 小游戏','GLM-Legal'].entries()){
 test(name+': the real current cover node renders both exact private archives, geometry and downloads',()=>{
  const {job,cover}=fixture(index),before=copy(job),artifact=JSON.parse(cover.artifact);
  const d=staticDocument(job,cover),images=[...d.querySelectorAll('img')];assert.equal(images.length,2);
  for(const role of ['cover_3_4','cover_4_3']){
   const archive=byRole(job,role),image=images.find(el=>el.getAttribute('src')===href(job,archive));assert.ok(image,role+' exact archive');assert.equal(image.style.objectFit,'contain');
   assert.equal(image.getAttribute('width'),String(archive.file.width));assert.equal(image.getAttribute('height'),String(archive.file.height));
   const frame=image.closest('[style]');assert.ok(frame);const ratio=role==='cover_3_4'?3/4:4/3;
   const raw=image.style.aspectRatio||image.parentElement.style.aspectRatio||image.parentElement.parentElement.style.aspectRatio;
   assert.ok(raw,'cover keeps its explicit source aspect ratio');const terms=raw.split('/').map(Number);assert.equal(terms.length===2?terms[0]/terms[1]:terms[0],ratio);
   const links=[...d.querySelectorAll('a')].filter(a=>a.getAttribute('href')?.startsWith(href(job,archive)));
   assert.ok(links.some(a=>a.getAttribute('target')==='_blank'),'full-size link');assert.ok(links.some(a=>a.hasAttribute('download')&&a.getAttribute('download')===archive.file.file_name),'download original');
   assert.equal(artifact.qa.site_archive_ids[role],archive.site_archive_id);
  }
  assert.ok(d.querySelector('details[data-site-promotion-preview]'));assert.deepEqual(job,before,'render is read-only');
 });
 test(name+': supplied external URLs cannot replace a validated private archive',()=>{
  const {job,cover}=fixture(index),artifact=JSON.parse(cover.artifact);artifact.url='https://untrusted.invalid/fake.png';artifact.qa.preview_url='javascript:alert(1)';cover.artifact=JSON.stringify(artifact);
  for(const a of job.facts.site_file_archives)a.url='https://untrusted.invalid/'+a.file.role;
  const d=staticDocument(job,cover);assert.equal(d.querySelectorAll('img').length,2);
  for(const el of d.querySelectorAll('a,img')){const url=el.getAttribute(el.tagName==='IMG'?'src':'href');assert.ok(url.startsWith('/api/site-archive?id='+job.id+'&archive=sitefile_'));assert.doesNotMatch(url,/untrusted|javascript:|token|owner_id/);}
 });
}

for(const [name,change] of [
 ['stale voice',a=>a.voice_provenance_id='candidate_voice_'+'0'.repeat(64)],
 ['wrong revision',a=>a.binding.revision++],['wrong source script',a=>a.binding.script_hash='0'.repeat(64)],
 ['wrong epoch',a=>a.binding.mode_epoch++],['wrong contract',a=>a.binding.contract_hash='0'.repeat(64)],
 ['wrong candidate',a=>a.binding.candidate_id='native_video_'+'0'.repeat(64)],['wrong video bytes',a=>a.binding.candidate_sha256='0'.repeat(64)],
 ['wrong project',a=>a.binding.project_id='00000000-0000-0000-0000-000000000000'],
 ['wrong timeline',a=>a.binding.timeline_id='00000000-0000-0000-0000-000000000000'],
 ['wrong approval',a=>a.owner_review_id='SYNTHETIC-old-review'],['wrong scope',a=>a.scope_id='media_scope_'+'0'.repeat(64)],
 ['wrong scope digest',a=>a.scope_hash='0'.repeat(64)],['unconfirmed archive',a=>a.status='sealed'],
 ['wrong stored bytes',a=>a.materialized_sha256='0'.repeat(64)],['missing manifest',a=>delete a.manifest_sha256],
 ['wrong post-video node',a=>a.post_video_delivery_id='native_draft_'+'0'.repeat(64)],
 ]){
 test('current preview refuses '+name+' instead of showing the stale file',()=>{const {job,cover}=fixture(),a=byRole(job,'cover_3_4');change(a);const d=staticDocument(job,cover);expectNoArchive(d,job,a);});
}
for(const status of ['invalidated','superseded'])test('a '+status+' cover node cannot expose files',()=>{const {job,cover}=fixture();cover.status=status;const d=staticDocument(job,cover);assert.equal(d.querySelector('img,a,details[data-site-promotion-preview]'),null);});
test('an older cover node is hidden when a later node exists',()=>{const {job,cover}=fixture();job.milestones.push({...copy(cover),id:'SYNTHETIC-new-cover',artifact_version:cover.artifact_version+1,status:'awaiting_human'});const d=staticDocument(job,cover);assert.equal(d.querySelector('img,a,details[data-site-promotion-preview]'),null);});
test('a current archive ID mismatch never falls back to the top-level artifact URL',()=>{const {job,cover}=fixture(),a=byRole(job,'cover_3_4'),artifact=JSON.parse(cover.artifact);artifact.qa.site_archive_ids.cover_3_4='sitefile_'+'0'.repeat(64);cover.artifact=JSON.stringify(artifact);const d=staticDocument(job,cover);expectNoArchive(d,job,a);});
test('preview cannot enroll an unrelated job by copying the same files',()=>{const {job,cover}=fixture();job.id='job_SYNTHETIC-unrelated';const d=staticDocument(job,cover);assert.equal(d.querySelector('img,a,details[data-site-promotion-preview]'),null);});

test('promotion full text is fetched only after expansion and shown from verified archived UTF-8 bytes',async t=>{
 const {job,cover}=fixture(),a=byRole(job,'promotion'),bytes=Buffer.from(realPromotionBody,'utf8');assert.equal(bytes.length,a.file.size_bytes);assert.equal(digest(bytes),a.file.sha256);
 const {calls}=await mount(t,job,cover,async(url,options)=>{assert.equal(url,href(job,a));assert.equal(options.cache,'no-store');assert.ok(options.signal);assert.equal(options.method,undefined);return textResponse(bytes,a.file.sha256);});
 assert.equal(calls.length,0);assert.equal(document.querySelector('pre[aria-label="本站宣发全文"]'),null);await expandPromotion();
 assert.equal(calls.length,1);assert.equal(document.querySelector('pre[aria-label="本站宣发全文"]')?.textContent,realPromotionBody);assert.equal(document.querySelector('[role="alert"]'),null);
});
test('promotion node follows site-promotion-file-v1 limits rather than its abbreviated metadata',async t=>{
 const {job}=fixture(),a=byRole(job,'promotion'),milestone=promotionMilestone(job),bytes=Buffer.from(realPromotionBody,'utf8');
 const {calls}=await mount(t,job,milestone,async url=>{assert.equal(url,href(job,a));return textResponse(bytes,a.file.sha256);});assert.equal(calls.length,0);await expandPromotion();assert.equal(calls.length,1);assert.equal(document.querySelector('pre')?.textContent,realPromotionBody);assert.doesNotMatch(document.querySelector('pre')?.textContent||'',/SYNTHETIC abbreviated metadata/);
});
for(const [name,responseFor] of [
 ['failed HTTP',(bytes,sha)=>textResponse(bytes,sha,{status:403})],
 ['wrong SHA header',(bytes,sha)=>textResponse(bytes,sha,{header:'0'.repeat(64)})],
 ['missing SHA header',(bytes,sha)=>new Response(bytes,{headers:{'Content-Type':'text/plain; charset=utf-8'}})],
 ['HTML content type',(bytes,sha)=>textResponse(bytes,sha,{type:'text/html'})],
 ['truncated actual bytes',(bytes,sha)=>textResponse(bytes.subarray(0,bytes.length-1),sha)],
 ['same-size altered bytes',(bytes,sha)=>{const changed=Buffer.from(bytes);changed[0]^=1;return textResponse(changed,sha);}],
 ]){
 test('promotion preview rejects '+name+' without displaying unchecked content',async t=>{const {job,cover}=fixture(),a=byRole(job,'promotion');await mount(t,job,cover,async()=>responseFor(Buffer.from(realPromotionBody,'utf8'),a.file.sha256));await expandPromotion();assert.equal(document.querySelector('pre[aria-label="本站宣发全文"]'),null);assert.ok(document.querySelector('[role="alert"]'),'visible read or verification error');assert.ok(document.querySelector('[role="alert"]').textContent.trim());});
}
test('matching SHA and byte count do not permit malformed UTF-8',async t=>{const {job,cover}=fixture(),bytes=Buffer.from([0xc3,0x28]),a=replacePromotionBytes(job,bytes);await mount(t,job,cover,async()=>textResponse(bytes,a.file.sha256));await expandPromotion();assert.equal(document.querySelector('pre[aria-label="本站宣发全文"]'),null);assert.ok(document.querySelector('[role="alert"]'));});
test('the current promotion archive ID must match the node before any fetch',async t=>{const {job,cover}=fixture(),artifact=JSON.parse(cover.artifact);artifact.qa.promotion_site_archive_id='sitefile_'+'0'.repeat(64);cover.artifact=JSON.stringify(artifact);const {calls}=await mount(t,job,cover,async()=>{throw Error('Must not fetch an unmatched archive');});assert.equal(document.querySelector('details[data-site-promotion-preview]'),null);assert.equal(calls.length,0);});
test('promotion limits reject another archive or digest rather than expose unchecked text',()=>{for(const field of ['site_archive_id','sha256']){const {job}=fixture(),m=promotionMilestone(job),v=JSON.parse(m.artifact),limits=JSON.parse(v.limits);limits[field]=field==='sha256'?'0'.repeat(64):'sitefile_'+'0'.repeat(64);v.limits=JSON.stringify(limits);m.artifact=JSON.stringify(v);assert.equal(staticDocument(job,m).querySelector('details[data-site-promotion-preview]'),null);}});
